"""Owner-only, local browser import for personal provisional pre-day forecast files.

Does not call JRDB, copy licensed rows to public pages, touch ticket or result
storage, claim official JRA readiness, or imply betting has occurred.
"""
HTML="<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#09172b\"><title>KEIBA NINE｜本人用の前日予想</title><link rel=\"stylesheet\" href=\"/owner-preday-forecast.css\"></head><body><main><a href=\"/\">← 本人用ホームへ</a><h1>前日予想・全36R</h1><p class=\"warning\"><b>本人用・前日暫定予想の閲覧ページです。</b> 予想は本人ログイン後に自動読み込みします。接続できない場合だけ保存済みの端末ファイルを使えます。5項目AIの正式評価、JRA公式の当日取消・馬場照合、購入済み馬券ではありません。見送りRも参考の組合せを表示します。</p><section><h2>明日の前日予想</h2><p class=\"hint\" id=\"fpCloudStatus\" role=\"status\">本人用の非公開予想を確認中です。読み込みにファイル選択は不要です。</p><button id=\"fpRefresh\" type=\"button\">最新版の予想を再読み込み</button><div class=\"toolbar\"><label for=\"fpTrack\">競馬場</label><select id=\"fpTrack\"><option value=\"\">全競馬場</option><option>東京</option><option>京都</option><option>福島</option><option>札幌</option><option>函館</option><option>新潟</option><option>中山</option><option>中京</option><option>阪神</option><option>小倉</option></select><label><input id=\"fpOnlyBuy\" type=\"checkbox\"> 買い候補だけ</label></div><p class=\"hint\" id=\"fpSummary\" role=\"status\">保存された予想ファイルを確認しています。</p><div id=\"fpRaces\"></div></section><details class=\"manual\"><summary>ファイルから手動で取り込む（通常は不要）</summary><section><h2>① 予想ファイルを読み込む</h2><p class=\"hint\">ChatGPTで作成した「keiba_nine_...private.json」をiPhoneの「ファイル」に保存し、下から選択。予想ファイル以外は拒否します。</p><label for=\"fpFile\">本人用の前日予想JSON</label><input id=\"fpFile\" type=\"file\" accept=\".json,application/json\"><button id=\"fpImport\" type=\"button\">内容を検査して本人端末に保存</button><p id=\"fpStatus\" role=\"status\">未選択。既存の5項目評価・買い目・購入記録は変更しません。</p></section></details><section><h2>データ管理</h2><p class=\"hint\">削除するのは、端末に手動取り込みした予想ファイルだけ。サーバー上の本人用前日予想は消えません。JRDB前日情報・手動5項目・馬券下書き・実購入記録は触りません。</p><button id=\"fpDelete\" type=\"button\">このページの予想だけ削除（確認あり）</button></section></main><script src=\"/owner-preday-forecast.js\" defer></script></body></html>"
CSS="*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#09172b;color:#f0f5ff;font:15px/1.65 system-ui,sans-serif}main{max-width:740px;padding:18px 13px 48px;margin:auto}a{color:#f1cf79}h1{font-size:25px;color:#edc56c}h2{font-size:19px;margin:0 0 12px}section{background:#142d48;border:1px solid #547493;border-radius:15px;padding:14px;margin:16px 0}.warning{background:#322a22;color:#ffe4ad;border:1px solid #927844;border-radius:12px;padding:14px;font-size:14px}.hint{color:#c1d0e3;font-size:13px}.toolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center}input[type=file],select{max-width:100%;font-size:16px;background:#0c2136;color:white;border:1px solid #839bb7;border-radius:10px;padding:10px;margin:8px 0}button{font-size:15px;color:#11223b;background:#edc56c;border:0;border-radius:11px;padding:10px 14px;font-weight:bold;cursor:pointer;margin:7px 0}button:disabled{opacity:.5}.card{border:1px solid #52728e;border-radius:12px;background:#10243c;margin:12px 0;padding:12px}.heading{display:flex;align-items:center;justify-content:space-between;gap:8px}.heading strong{font-size:17px}.status{color:#f3deb2;font-size:12px}.line{margin:4px 0;font-weight:600}.label{color:#f3cc72;display:inline-block;min-width:2.5em}.rowbuttons{display:flex;flex-wrap:wrap;gap:10px}.rowbuttons a{display:inline-block;border:1px solid #6c89a3;border-radius:10px;padding:8px 12px}.reason{font-size:13px;color:#ccd9e7}details.manual{margin:18px 0}details.manual summary{color:#edc56c;font-weight:bold;padding:11px;border:1px solid #547493;border-radius:10px;cursor:pointer}"
JS="(()=>{'use strict';\nconst STORAGE='keiba-nine-owner-preday-analysis-v1';\nconst TRACKS=['東京','京都','福島','札幌','函館','新潟','中山','中京','阪神','小倉'];\nconst $=id=>document.getElementById(id);\nconst MARKER='keiba-nine-private-preday-review-v1';\nlet current=null,serverForecast=null;\nfunction validDate(date){\n if(typeof date!=='string'||!/^20\\d{2}-\\d{2}-\\d{2}$/.test(date))return false;\n const d=new Date(date+'T12:00:00Z');\n return Number.isFinite(d.valueOf())&&d.toISOString().slice(0,10)===date;\n}\nfunction picks(data){\n if(!data||data.schema!==MARKER||!validDate(data.date)||\n   !Array.isArray(data.races)||data.races.length<1||data.races.length>36)\n  throw Error('競馬ナイン本人用の予想ファイルではありません。');\n const seen=new Set(),result=[];\n for(const r of data.races){\n  if(!r||!TRACKS.includes(r.track)||!Number.isInteger(r.race)||\n    r.race<1||r.race>12||typeof r.time!=='string'||\n    !/^([01]\\d|2[0-3]):[0-5]\\d$/.test(r.time)||\n    typeof r.course!=='string'||r.course.length<2||r.course.length>12||\n    !Number.isInteger(r.field)||r.field<3||r.field>18||\n    !Array.isArray(r.rank)||r.rank.length!==7||\n    !['買い候補','見送り'].includes(r.status)||\n    !Number.isInteger(r.confidence)||r.confidence<1||r.confidence>5||\n    r.provisional!==true||r.jraOfficialConfirmed!==false||\n    r.fullFactorVerified!==false||typeof r.note!=='string'||r.note.length>240||\n    !Array.isArray(r.headNames)||r.headNames.length!==2||\n    r.headNames.some(x=>x!==null&&(typeof x!=='string'||x.length>35)))\n   throw Error('予想の日付・頭数・安全状態・レース欄が不正です。');\n  const key=r.track+'|'+r.race;\n  if(seen.has(key))throw Error('同じ競馬場・同じRが重複しています。');\n  seen.add(key);\n  const known=new Set();\n  if(r.rank.some(x=>!Number.isInteger(x)||x<1||x>r.field||known.has(x)||\n     (known.add(x),false)))throw Error('馬番または評価順が不正です。');\n  if(![r.first,r.second,r.third].every(x=>Array.isArray(x)))throw Error('3連単欄が不正です。');\n  const f=r.first.length,s=r.second.length,t=r.third.length;\n  if(f<1||f>3||s<f||t<s||t>7||\n      ![r.first,r.second,r.third].every(a=>a.every((num,i)=>num===r.rank[i])))\n   throw Error('3連単フォーメーションが評価順と一致しません。');\n  const ticket=new Set();\n  for(const a of r.first)for(const b of r.second)for(const c of r.third){\n   if(a!==b&&a!==c&&b!==c)ticket.add([a,b,c].join('-'));\n  }\n  if(!Number.isInteger(r.points)||r.points!==ticket.size||\n     r.points<1||r.points>48)\n   throw Error('3連単の点数が一致しません。');\n  // Store only known presentation data; never persist metadata, source text,\n  // provider metrics, API keys, paid fields or actual purchase information.\n  result.push({track:r.track,race:r.race,time:r.time,course:r.course,\n    rank:[...r.rank],first:[...r.first],second:[...r.second],third:[...r.third],\n    points:r.points,status:r.status,confidence:r.confidence,\n    headNames:[...r.headNames],note:r.note});\n }\n result.sort((a,b)=>TRACKS.indexOf(a.track)-TRACKS.indexOf(b.track)||a.race-b.race);\n return {schema:MARKER,date:data.date,races:result};\n}\nfunction element(tag,text){\n const el=document.createElement(tag);\n if(text!==undefined)el.textContent=String(text);\n return el;\n}\nfunction textLine(parent,title,value){\n const p=element('p');p.className='line';\n const span=element('span',title);span.className='label';\n p.append(span,element('span',value));parent.append(p);\n}\nfunction render(){\n const host=$('fpRaces');host.replaceChildren();\n if(!current){\n  $('fpSummary').textContent='まだ予想ファイルがありません。上のJSONを読み込んでな。';\n  return;\n }\n const track=$('fpTrack').value,buy=$('fpOnlyBuy').checked;\n const rows=current.races.filter(x=>(!track||x.track===track)&&(!buy||x.status==='買い候補'));\n $('fpSummary').textContent=current.date+'｜全'+current.races.length+'R／表示'+rows.length+\n   'R。すべて前日暫定、公式の当日照合・5項目AIは未完了。';\n for(const r of rows){\n  const card=element('article');card.className='card';\n  const head=element('div');head.className='heading';\n  head.append(element('strong',r.track+r.race+'R '+r.time+' '+r.course),\n    element('span',r.status+'／勝負度'+r.confidence+'/5'));\n  card.append(head);\n  const winner=r.first.map((n,i)=>n+' '+(r.headNames[i]||'')).join('・');\n  const p=element('p','1着候補：'+winner);card.append(p);\n  const order=element('p','良い馬順（暫定）：'+r.rank.join(' > '));order.className='reason';card.append(order);\n  const group=element('div');group.className='bet';\n  textLine(group,'1着',r.first.join(' '));\n  textLine(group,'2着',r.second.join(' '));\n  textLine(group,'3着',r.third.join(' '));\n  group.append(element('p','3連単 '+r.points+'点／各100円なら'+(r.points*100).toLocaleString('ja-JP')+'円'));\n  card.append(group);\n  const note=element('p',r.note);note.className='reason';card.append(note);\n  const nav=element('div');nav.className='rowbuttons';\n  const link=element('a','同じRの評価画面へ');\n  link.href='/my-scorecard#'+new URLSearchParams({\n    select:'v1',date:current.date,track:r.track,race:String(r.race)\n  }).toString();\n  nav.append(link);\n  const copy=element('button','フォーメーションをコピー');\n  const msg=r.track+r.race+'R 1着 '+r.first.join(',')+\n    ' / 2着 '+r.second.join(',')+' / 3着 '+r.third.join(',')+' = '+r.points+'点（前日暫定）';\n  copy.onclick=()=>{if(navigator?.clipboard?.writeText)\n    navigator.clipboard.writeText(msg).then(()=>copy.textContent='コピー済み')\n      .catch(()=>copy.textContent='画面の買い目を長押しコピーしてな。');\n    else copy.textContent='画面の買い目を長押しコピーしてな。';\n  };\n  nav.append(copy);card.append(nav);host.append(card);\n }\n}\n$('fpFile').onchange=()=>{$('fpStatus').textContent=\n $('fpFile').files?.[0]?'選択済み。検査ボタンで読み込めます。':'ファイル未選択。';};\n$('fpTrack').onchange=render;$('fpOnlyBuy').onchange=render;\n$('fpImport').onclick=async()=>{\n try{\n  const file=$('fpFile').files?.[0];\n  if(!file||file.size<=0||file.size>200000)throw Error('200KB以内のJSONファイルを選んでな。');\n  const content=await file.text();\n  if(content.length>200000)throw Error('予想ファイルが大きすぎます。');\n  const result=picks(JSON.parse(content));\n  if(!confirm(result.date+'・'+result.races.length+'Rの前日暫定予想をこのiPhoneに保存しますか？\\n実購入・5項目評価・馬券下書きは変更しません。'))return;\n  localStorage.setItem(STORAGE,JSON.stringify(result));\n  current=result;render();\n  $('fpStatus').textContent=result.date+'の'+result.races.length+\n    'Rを保存しました。JRA当日確認・AI評価は未完了です。';\n }catch(e){$('fpStatus').textContent='取り込めません：'+\n   (e instanceof Error?e.message:'内容を確認してな。');}\n};\n$('fpRefresh').onclick=()=>loadOwnerForecast();\nasync function loadOwnerForecast(){\n $('fpCloudStatus').textContent='非公開の本人用予想を確認しています。';\n try{\n  const response=await fetch('/api/owner-preday-forecast',{\n   credentials:'same-origin',cache:'no-store',\n   headers:{'X-Keiba-Request':'private','Accept':'application/json'}\n  });\n  if(!response.ok)throw Error('非公開予想を取得できません。');\n  const result=await response.json();\n  if(!result||typeof result!=='object'||result.available!==true){\n   $('fpCloudStatus').textContent='サーバー上の前日予想はまだ未設定。手動取込データがあれば表示します。';\n   return;\n  }\n  const safe=picks(result.forecast);\n  if(!result.forecast||result.forecast.sourceKind!=='owner-private-authored-preday'||\n     result.forecast.predictionReady!==false||result.forecast.officialJraVerified!==false||\n     result.forecast.purchased!==false||result.forecast.raceCount!==safe.races.length)\n   throw Error('非公開予想の安全表示情報が一致しません。');\n  serverForecast=safe;current=safe;\n  $('fpCloudStatus').textContent=safe.date+'｜'+safe.races.length+\n   'Rを本人用サーバーから自動表示。ファイルの選択・保存は不要。前日暫定／当日JRA未照合。';\n  render();\n }catch(_){\n  $('fpCloudStatus').textContent='サーバーの予想表示を確認できません。既存の端末内予想があれば閲覧できます。';\n }\n}\n$('fpDelete').onclick=()=>{\n if(!current)return;\n if(!confirm('本人用の取り込み済み前日予想だけを削除しますか？\\n既存の馬券・採点・JRDB前日情報は残ります。'))return;\n try{localStorage.removeItem(STORAGE);current=serverForecast;render();\n  $('fpStatus').textContent='端末の手動取込データだけ削除。サーバーの予想は維持されます。';\n }catch(e){$('fpStatus').textContent='削除できません。端末の保存設定を確認してな。';}\n};\ntry{\n const raw=localStorage.getItem(STORAGE);\n if(raw){current=picks(JSON.parse(raw));\n   $('fpStatus').textContent='端末に保存済みの前日暫定予想を表示しています。';}\n render();\n}catch(_){current=null;$('fpSummary').textContent='端末の保存資料を読み込めません。サーバーを確認します。';}\nloadOwnerForecast();\n})();"
